/// <summary>
/// Derived Item validity object Quotation class 
/// </summary>
class NDX_ItemValidityObjectQuotation extends NDX_ItemValidityObject
{
    QuotationId check_QuotationId;
    KCS_KBVBuildingProjectID check_KCS_KBVBuildingProjectID;

}

Method.Source:
protected void new(QuotationId _check_QuotationId, KCS_KBVBuildingProjectID _check_KCS_KBVBuildingProjectID)
{
    check_QuotationId = _check_QuotationId;
    check_KCS_KBVBuildingProjectID = _check_KCS_KBVBuildingProjectID;
}

static public NDX_ItemValidityObjectQuotation construct(QuotationId _check_QuotationId, KCS_KBVBuildingProjectID _check_KCS_KBVBuildingProjectID)
{
    return new NDX_ItemValidityObjectQuotation(_check_QuotationId,_check_KCS_KBVBuildingProjectID);
}

public QuotationId parmCheck_QuotationId(QuotationId _check_QuotationId = check_QuotationId)
{
    check_QuotationId = _check_QuotationId;
    return check_QuotationId;
}

public KCS_KBVBuildingProjectID parmCheck_KCS_KBVBuildingProjectID(KCS_KBVBuildingProjectID _check_KCS_KBVBuildingProjectID = check_KCS_KBVBuildingProjectID)
{
    check_KCS_KBVBuildingProjectID = _check_KCS_KBVBuildingProjectID;
    return check_KCS_KBVBuildingProjectID;
}

public void startTest(FormRun _caller)
{
    container result;
    NDXValidityMessage message;
    INDX_ItemValidityTest ndx_ItemValidityTestForm = _caller as INDX_ItemValidityTest;
    //if caller Quotation
    result = NDX_ItemValidity::checkValidityQuotation(check_ItemId,
                                                    check_QuotationId,
                                                    check_KCS_KBVBuildingProjectID,
                                                    check_CustAccount,
                                                    check_Date);

    message = NDX_ItemValidity::conErrorMessage2ValidityMessage(conPeek(result,2));
    ndx_ItemValidityTestForm.setMessage(message);

    // 2. komplette-Validierungsprüfung
    result = NDX_ItemValidity::checkValidityQuotation(check_ItemId,
                                                    check_QuotationId,
                                                    check_KCS_KBVBuildingProjectID,
                                                    check_CustAccount,
                                                    check_Date,
                                                    true);

    message = NDX_ItemValidity::conErrorMessage2ValidityMessage(conPeek(result,2));
    ndx_ItemValidityTestForm.setMessageAll(message);
}
